import { useRmTickets } from "@/hooks/api/useRmTickets";
import RmDashboardPage from "@/app/(roles)/rm/client-info/page";
import type { RequestTicket } from "@/lib/rm/tickets";

function ticket(overrides: Partial<RequestTicket> = {}): RequestTicket {
  return {
    ref: "REQ-1", client: "Ardent Capital", contact: "M", email: "m@x.com", account: "IB-1",
    type: "Allotment", ccy: "USD", cash: "1", mult: "1×", date: "Jun 01",
    status: "New", tone: "warm", message: "m",
    ...overrides,
  };
}

beforeEach(() => vi.clearAllMocks());

describe("ADM-5 Requests Tickets rail card — derived from useRmTickets(), not REQUEST_TICKETS", () => {
  it("counts only open (non-terminal) tickets per type; Resolved/Declined are excluded", () => {
    vi.mocked(useRmTickets).mockReturnValue({
      data: [
        ticket({ ref: "REQ-1", type: "Allotment", status: "New" }),
        ticket({ ref: "REQ-2", type: "Allotment", status: "Resolved" }), // terminal, excluded
        ticket({ ref: "REQ-3", type: "Redemption", status: "In Progress" }),
        ticket({ ref: "REQ-4", type: "Redemption", status: "Declined" }), // terminal, excluded
        ticket({ ref: "REQ-5", type: "Redemption", status: "Resolved" }), // terminal, excluded
      ],
      loading: false, error: null, refetch: vi.fn(),
    } as never);

    render(<RmDashboardPage />);
    const card = screen.getByText("Requests Tickets").closest("section")!;
    // total open = REQ-1 (Allotment) + REQ-3 (Redemption) = 2
    expect(within(card).getByText("2")).toBeInTheDocument();
  });

  it("an empty ticket list renders 0, not a crash from an empty-array reduce", () => {
    vi.mocked(useRmTickets).mockReturnValue({ data: [], loading: false, error: null, refetch: vi.fn() } as never);
    expect(() => render(<RmDashboardPage />)).not.toThrow();
    const card = screen.getByText("Requests Tickets").closest("section")!;
    // SummaryCard always mounts both the header total and the 2 per-type rows (never
    // conditionally removed), so an all-zero state renders multiple "0" text nodes —
    // assert at least one exists rather than a single unique match.
    expect(within(card).getAllByText("0").length).toBeGreaterThan(0);
  });

  it("a null data (still loading) does not crash the count derivation", () => {
    vi.mocked(useRmTickets).mockReturnValue({ data: null, loading: true, error: null, refetch: vi.fn() } as never);
    expect(() => render(<RmDashboardPage />)).not.toThrow();
  });
});
